import com.bridger.momentum.*;
import java.nio.file.*;
import java.util.*;
public final class ModernBlocksRegression {
 public static void main(String[] args)throws Exception{ModernBlockCatalog catalog=new ModernBlockCatalog(Paths.get(args[0]));if(catalog.blocks().size()!=1198||!catalog.blocks().contains("modern:pale_oak_planks"))throw new AssertionError("Incomplete 26.2 block catalog: "+catalog.blocks().size()+" / "+catalog.blocks().subList(0,Math.min(3,catalog.blocks().size())));int count=0,fallback=0;Set<String> resources=new HashSet<>();for(String key:catalog.blocks()){List<ModernBlockCatalog.Model> models=catalog.models(key);if(models.isEmpty())throw new AssertionError("No model: "+key);for(ModernBlockCatalog.Model model:models)if(model.fallback)fallback++;for(String texture:ModernBlockCatalog.textures(models)){String path="textures/"+texture.substring("bridgetap:".length())+".png";if(resources.add(path)){byte[] image=catalog.resource("bridgetap",path);if(image.length<8||image[0]!=(byte)137||image[1]!=80)throw new AssertionError("Missing PNG: "+texture);}}count++;}try{catalog.resource("bridgetap","textures/modern/../../secret");throw new AssertionError("Path traversal accepted");}catch(java.io.IOException good){}System.out.println("PASS: "+count+" official 26.2 block appearances, parent/texture resolution and "+resources.size()+" PNG resources; "+fallback+" special-model cube fallbacks");}
}
